<template>
<div class="shell">
  <header class="top"><span class="brand-mark">鑫</span><strong>主播工作台</strong><span>{{siteUser?.nickName||'请登录网站账号'}}</span><el-tag :type="state.loginRequired?'warning':'info'">{{state.loginRequired?'百应需要登录':'百应采集'}}</el-tag><el-button v-if="!siteUser" @click="loginOpen=true">登录网站账号</el-button></header>
  <div class="layout"><nav><button v-for="item in pages" :key="item[0]" :class="{active:page===item[0]}" @click="changePage(item[0])"><el-icon><component :is="pageIcons[item[0]]"/></el-icon>{{item[1]}}</button><small>版本 {{state.version}}<br>网站与App共用记录</small></nav>
  <main>
    <el-alert v-if="error" :title="error" type="error" show-icon closable @close="error=''"/>
    <section v-if="page==='work'" class="work-page">
      <header class="work-heading"><div><div class="room-heading"><h2>{{state.roomName||'主播数据上报'}}</h2><span class="connection" :class="{warning:!state.complete}"><el-icon><CircleCheck v-if="state.complete"/><Warning v-else/></el-icon>{{state.complete?'指标已齐全':state.loginRequired?'百应需要登录':'等待采集'}}</span></div><p>{{state.liveStartTime?shortDate(state.liveStartTime)+' '+clock(state.liveStartTime)+' 开播':'请先登录百应并选择场次'}}<span v-if="state.capturedAt"> · 数据采集于 {{clock(state.capturedAt)}}</span></p></div><div class="actions"><el-button @click="sessionDetail=!sessionDetail">场次详情</el-button><el-button :loading="busy" @click="perform(()=>native('selectSession'))"><el-icon><Switch/></el-icon>{{state.loginRequired?'登录百应':'切换场次'}}</el-button></div></header>
      <div v-if="sessionDetail" class="session-detail"><span>场次标题：{{state.title||'—'}}</span><span>场次 ID：{{state.roomId||'待选择'}}</span><span>开播时间：{{dt(state.liveStartTime)}}</span></div>
      <div v-if="!state.complete" class="capture-status"><el-icon><InfoFilled/></el-icon><span>{{state.status||'等待百应返回数据'}}</span><el-button text @click="perform(()=>native('showCollector'))">查看百应页面</el-button><el-button text @click="perform(()=>native('logs'))">查看日志</el-button></div>
      <div v-if="!siteUser" class="access-notice"><span>请登录网站账号后上报，百应账号用于采集数据。</span><el-button type="primary" @click="loginOpen=true">登录网站账号</el-button></div>
      <el-alert v-if="context&&!context.roomMatched" title="未匹配到系统直播间，绑定后才可上传" type="warning" :closable="false"><template v-if="manager"><el-select v-model="bindRoom" placeholder="选择系统直播间" filterable><el-option v-for="room in rooms" :key="room.roomId" :label="room.roomName" :value="room.roomId"/></el-select><el-button @click="bindCurrent">确认绑定</el-button></template><span v-else>请联系管理员确认直播间绑定。</span></el-alert>
      <section class="cumulative" aria-label="本场累计"><div class="cumulative-label"><b>本场累计</b><span>截至最近采集</span></div><div class="cum-metric" v-for="field in topMetrics" :key="field[0]"><span>{{field[1]}}</span><b>{{rawMetric(field)}}</b></div><el-popover placement="bottom-end" :width="350" trigger="click"><template #reference><el-button text>完整指标<el-icon><ArrowDown/></el-icon></el-button></template><div class="all-metrics"><div v-for="field in extraMetrics" :key="field[0]"><span>{{field[1]}}</span><b>{{rawMetric(field)}}</b></div></div></el-popover></section>
      <section class="cumulative" aria-label="复盘漏斗"><div class="cumulative-label"><b>复盘漏斗</b><span>{{state.funnelCapturedAt ? '采集于 '+clock(state.funnelCapturedAt) : '等待接口返回'}}</span></div><div class="cum-metric" v-for="field in funnelMetrics" :key="field[0]"><span>{{field[1]}}</span><b>{{rawMetric(field)}}</b></div></section>
      <p class="field-hint">观看互动率＝内容互动人数÷直播间观看人数，使用同一份漏斗响应；与大屏累计观看人数分开保存。</p>
      <div class="focus-layout"><section class="report-box">
        <div class="section-heading"><h3>本次上报</h3><span class="phase" :class="{ready:preview}">{{busy?'正在处理…':pending?'有待确认上报':preview?'预览已就绪':'待采集预览'}}</span></div>
        <div class="report-inputs"><div><label>归属主播</label><el-select v-model="anchorId" placeholder="选择实际上播主播" filterable :disabled="busy||!!pending" @change="invalidatePreview"><el-option v-for="anchor in context?.anchors||[]" :key="anchor.userId" :label="anchor.userName" :value="anchor.userId" :disabled="!manager&&String(anchor.userId)!==String(siteUser?.userId)"/></el-select><span class="field-hint" v-if="siteUser&&context?.roomMatched&&!context.anchors?.length">尚未分配可上报主播，请联系管理员。</span></div><div><label>上报区间 · {{shortDate(preview?.startTime||baselineStart)}}</label><div class="report-range">{{clock(preview?.startTime||baselineStart)}} <span>→</span> {{preview?rangeEnd(preview.startTime,preview.endTime):'采集后确定'}}</div><span class="field-hint">{{preview?'时长 '+preciseDuration(preview):'从上次已确认区间接续'}}</span></div></div>
        <el-alert v-if="context?.effectiveBaseline?.estimatedBaseline" title="从已确认的人工区间接续，基线包含人工数据" type="info" :closable="false"/>
        <div v-if="pending" class="pending"><h3>请先核对上一条上报</h3><p>提交结果尚待确认。重试原上报不会重复写入。</p><el-button type="primary" :loading="busy" @click="recoverPending">核对并重试原上报</el-button><el-button @click="discardPending">放弃待确认草稿</el-button></div>
        <div v-else-if="preview" class="preview-content"><div class="preview-heading"><h4>本次区间数据</h4><span>归属 {{selectedAnchor}}</span></div><el-alert v-if="preview.firstReport" title="首次上报从开播起计算，请确认前面没有其他主播漏报" type="warning" :closable="false"/><div class="delta-grid"><div class="delta-metric" v-for="field in primarySegmentMetrics" :key="field.key"><span>{{field.label}}</span><b>{{segmentValue(preview,field)}}</b></div></div></div>
        <div v-else-if="!pending" class="preview-empty"><el-icon><DocumentChecked/></el-icon><div><b>{{busy?'正在准备本次区间数据':'选好主播，采集并预览'}}</b><p>先核对区间数据，确认后再提交。</p></div></div>
        <el-collapse v-if="!pending" v-model="expandedDetails" class="interval-details"><el-collapse-item title="区间明细与上次参考" name="details"><div class="comparison-wrap"><table class="comparison"><thead><tr><th scope="col">指标</th><th scope="col">本次区间<small>{{selectedAnchor||'待选择主播'}}</small></th><th scope="col">上次已上报<small>{{context?.lastReport?.anchorName||'本场暂无记录'}}</small></th></tr></thead><tbody><tr v-for="field in segmentMetrics" :key="field.key"><th scope="row">{{field.label}}</th><td>{{preview?segmentValue(preview,field):'—'}}</td><td>{{context?.lastReport?segmentValue(context.lastReport,field):'—'}}</td></tr></tbody></table></div><p class="comparison-note" v-if="context?.lastReport">上次区间：{{intervalLabel(context.lastReport)}} · 时长 {{preciseDuration(context.lastReport)}}。区间时长不同，仅供核对参考。</p><p class="comparison-note" v-else>本场尚未上报；首次区间从开播时间开始计算。</p><p class="comparison-note">互动率包含估算；缺失值显示“—”，区间比例由服务器计算。</p></el-collapse-item></el-collapse>
        <footer class="report-footer" v-if="!pending"><div><span>操作账号：{{siteUser?.nickName||'未登录'}}</span><small>{{busy?'正在采集或处理，请稍候':preview?'请核对主播、时间与区间数据后确认':'采集完成后生成预览，不会直接提交'}}</small></div><div class="actions"><el-button v-if="preview" :disabled="busy" @click="collectPreview"><el-icon><Refresh/></el-icon>重新采集</el-button><el-button v-if="preview" type="primary" :loading="busy" @click="submit">确认上报</el-button><el-button v-else type="primary" :loading="busy" :disabled="!siteUser||!anchorId||!context?.roomMatched||!!pending" @click="collectPreview"><el-icon><Refresh/></el-icon>采集并预览</el-button></div></footer>
        <div class="submit-success" v-if="success" role="status"><el-icon><CircleCheck/></el-icon><span>{{success}}</span><el-button text @click="openCurrentRecords">查看记录</el-button></div>
      </section><aside class="reference-panel"><section><h3>上次已上报</h3><template v-if="context?.lastReport"><div class="last-anchor"><span class="reference-avatar">{{context.lastReport.anchorName?.slice(0,1)}}</span><div><b>{{context.lastReport.anchorName}}</b><small>结束于 {{shortDate(context.lastReport.endTime)}} {{clock(context.lastReport.endTime)}}</small></div></div><dl class="reference-values"><div><dt>上报区间</dt><dd>{{intervalLabel(context.lastReport)}}</dd></div><div><dt>成交金额</dt><dd>¥{{money(context.lastReport.gmvDelta)}}</dd></div><div><dt>本次接续时间</dt><dd>{{clock(baselineStart)}}</dd></div></dl></template><p v-else>本场尚未上报，首条将从开播时间开始。</p></section><section class="recent-section"><div class="section-heading"><h3>本场上报记录</h3><span>{{context?.segments?.length||0}} 条</span></div><div v-for="row in recentSegments" :key="row.segmentId" class="recent-record"><div><b>{{row.anchorName}}</b><small>{{intervalLabel(row)}}</small></div><span>¥{{money(row.gmvDelta)}}</span></div><p v-if="!recentSegments.length">暂无记录</p><el-button v-if="siteUser" text @click="openCurrentRecords">查看完整记录 →</el-button></section><section class="help-section"><el-button text @click="perform(()=>native('help'))"><el-icon><QuestionFilled/></el-icon>使用说明</el-button><el-button text @click="perform(()=>native('logs'))">运行日志</el-button></section></aside></div>
    </section>
    <section v-if="page==='records'">
      <div class="heading"><div><h2>上报记录</h2><p>查看、补录和调整主播区间</p></div><el-button v-if="manager" type="primary" :disabled="!detail.sessions?.length" @click="openCreate">新增补录</el-button></div>
      <div class="filters"><el-select v-model="roomId" filterable placeholder="选择直播间" @change="loadDetail"><el-option v-for="room in rooms" :key="room.roomId" :label="room.roomName" :value="room.roomId"/></el-select><el-select v-model="range" @change="loadDetail"><el-option label="今天" value="0"/><el-option label="近7天" value="6"/><el-option label="近30天" value="29"/><el-option label="自定义" value="custom"/></el-select><el-date-picker v-if="range==='custom'" v-model="dates" type="daterange" value-format="YYYY-MM-DD" @change="loadDetail"/><el-button @click="loadDetail">刷新</el-button></div>
      <el-table :data="recordRows" border stripe><el-table-column type="expand"><template #default="{row}"><p>操作人：{{row.operatorName||'历史记录'}} · App版本：{{row.clientVersion||'—'}} · {{row.remark}}</p><el-button @click="showSnapshots(row.sessionId)">查看快照与操作日志</el-button></template></el-table-column><el-table-column label="开播时间" width="155"><template #default="{row}">{{dt(row.liveStartTime)}}</template></el-table-column><el-table-column prop="anchorName" label="主播" width="110"/><el-table-column label="上播区间" width="280"><template #default="{row}">{{dt(row.startTime)}} 至 {{dt(row.endTime)}}</template></el-table-column><el-table-column label="时长" width="90"><template #default="{row}">{{duration(row)}}</template></el-table-column><el-table-column label="来源" width="100"><template #default="{row}">{{source(row.source)}}</template></el-table-column><el-table-column v-for="metric in segmentMetrics" :key="metric.key" :label="metric.label" width="115"><template #default="{row}">{{segmentValue(row,metric)}}</template></el-table-column><el-table-column v-if="manager" fixed="right" label="操作" width="85"><template #default="{row}"><el-button text @click="openEdit(row)">调整</el-button></template></el-table-column></el-table>
    </section>
    <section v-if="page==='anchors'&&manager">
      <div class="heading"><div><h2>直播间主播分配</h2><p>保存后App与网站同步；不修改历史上报</p></div></div><div class="filters"><el-select v-model="roomId" filterable @change="loadDetail"><el-option v-for="room in rooms" :key="room.roomId" :label="room.roomName" :value="room.roomId"/></el-select><el-select v-model="copyRoom" filterable placeholder="从其他直播间复制名单"><el-option v-for="room in rooms.filter(r=>r.roomId!==roomId)" :key="room.roomId" :label="room.roomName" :value="room.roomId"/></el-select><el-button :disabled="!copyRoom" @click="copyAnchors">带入名单</el-button></div>
      <el-transfer v-model="assigned" filterable filter-placeholder="搜索系统用户" :data="(detail.staff||[]).map(u=>({key:u.userId,label:u.userName}))" :titles="['系统用户','可上报主播']"/><p>新增：{{assignmentChange.add.join('、')||'无'}}；移除：{{assignmentChange.remove.join('、')||'无'}}</p><el-button type="primary" :loading="busy" @click="saveAnchors">保存主播分配</el-button>
    </section>
    <section v-if="page==='settings'">
      <div class="heading"><div><h2>设置与更新</h2><p>账号、采集日志和软件版本</p></div></div>
      <div class="setting"><div><h3>启动设置</h3><p>登录 Windows 后在系统托盘启动，不会自动提交上报。最小化进入托盘，关闭按钮退出。</p></div><el-switch :model-value="!!state.startupEnabled" active-text="开机自启" @change="toggleStartup"/></div>
      <div class="setting"><div><h3>使用帮助</h3><p>安装、登录、采集上报、主播分配、更新和常见问题；支持离线阅读。</p></div><el-button @click="perform(()=>native('help'))">打开使用说明</el-button></div>
      <div class="setting"><div><h3>网站账号</h3><p>{{siteUser?.nickName||'尚未登录'}} · 用于上传和操作留痕</p></div><el-button @click="siteUser?logout():loginOpen=true">{{siteUser?'退出网站账号':'登录网站账号'}}</el-button></div>
      <div class="setting"><div><h3>百应账号</h3><p>登录信息仅保存在本机</p></div><el-button @click="perform(()=>native('selectSession'))">打开百应 / 切换场次</el-button><el-button @click="perform(()=>native('signOut'))">退出百应</el-button></div>
      <div class="setting"><div><h3>软件更新 · {{state.version}}</h3><p>从鑫客网站检查、下载并校验安装包</p></div><el-button :disabled="busy||!!preview||!!pending||editOpen" @click="perform(()=>native('update'))">检查更新</el-button></div>
      <div class="setting"><div><h3>运行日志</h3><p>查看采集、上传、登录和更新的处理结果</p></div><el-select v-model="logCategory"><el-option v-for="name in ['全部','采集','上传','登录','更新']" :key="name" :label="name" :value="name"/></el-select><el-button @click="perform(()=>native('logs'))">打开原始日志</el-button></div><pre class="logs">{{filteredLogs}}</pre>
    </section>
  </main></div>
  <el-dialog v-model="loginOpen" title="登录鑫客网站账号" width="420px" :close-on-click-modal="false"><el-form label-position="top" @submit.prevent="login"><el-form-item label="账号"><el-input v-model="credentials.username" autocomplete="username"/></el-form-item><el-form-item label="密码"><el-input v-model="credentials.password" type="password" show-password autocomplete="current-password" @keyup.enter="login"/></el-form-item><el-form-item v-if="captcha.captchaEnabled!==false" label="验证码"><div class="captcha"><el-input v-model="credentials.code" @keyup.enter="login"/><img v-if="captcha.img" :src="'data:image/png;base64,'+captcha.img" alt="验证码，点击刷新" @click="loadCaptcha"/></div></el-form-item><el-button type="primary" :loading="busy" @click="login">登录</el-button></el-form></el-dialog>
  <el-dialog v-model="editOpen" :title="editing?'调整主播记录':'补录主播记录'" width="min(800px,94vw)" :close-on-click-modal="false"><el-alert title="按实际区间填写，保存后重新计算相邻记录。" type="warning" :closable="false"/><el-form label-position="top"><div class="form-grid"><el-form-item v-if="!editing" label="直播场次"><el-select v-model="edit.sessionId" @change="selectEditSession"><el-option v-for="session in detail.sessions||[]" :key="session.sessionId" :label="dt(session.liveStartTime)" :value="session.sessionId"/></el-select></el-form-item><el-form-item v-if="!editing" label="漏报位置"><el-select v-model="edit.position" @change="selectPosition"><el-option v-for="position in positions" :key="position.value" :label="position.label" :value="position.value"/></el-select></el-form-item><el-form-item label="主播"><el-select v-model="edit.anchorUserId"><el-option v-for="u in detail.anchors||[]" :key="u.userId" :label="u.userName" :value="u.userId"/></el-select></el-form-item><el-form-item label="开始时间"><el-date-picker v-model="edit.startTime" type="datetime" value-format="YYYY-MM-DD HH:mm:ss" :disabled="!editing"/></el-form-item><el-form-item label="结束时间"><el-date-picker v-model="edit.endTime" type="datetime" value-format="YYYY-MM-DD HH:mm:ss"/></el-form-item><el-form-item v-for="metric in segmentMetrics" :key="metric.key" :label="metric.label"><el-input-number v-model="edit[metric.key]" :min="0" :max="metric.type==='rate'?100:999999999999" :precision="metric.type==='number'?0:2"/></el-form-item></div><el-form-item label="原因"><el-input v-model="edit.reason" type="textarea" maxlength="500"/></el-form-item><p v-if="affected">影响后续记录：{{affected.anchorName}}，请将带入值改为漏报时段的实际数据。</p></el-form><template #footer><el-button v-if="editing" type="danger" plain @click="voidReport">作废上报</el-button><el-button @click="editOpen=false">取消</el-button><el-button type="primary" :loading="busy" @click="saveEdit">{{editing?'保存调整':'确认补录'}}</el-button></template></el-dialog>
  <el-dialog v-model="auditOpen" title="场次采集快照与操作日志" width="min(1000px,95vw)"><el-tabs><el-tab-pane label="采集快照"><el-table :data="audit.snapshots||[]"><el-table-column prop="capturedAt" label="采集时间" width="190"/><el-table-column prop="watchTotal" label="累计观看"/><el-table-column prop="gmvTotal" label="累计成交金额"/><el-table-column prop="adCostTotal" label="累计消耗"/></el-table></el-tab-pane><el-tab-pane label="操作记录"><el-table :data="audit.corrections||[]"><el-table-column prop="correctedAt" label="操作时间"/><el-table-column prop="correctedName" label="操作人"/><el-table-column prop="actionType" label="类型"/><el-table-column prop="reason" label="原因"/></el-table></el-tab-pane></el-tabs></el-dialog>
</div>
</template>
<script setup>
import {ref,reactive,computed,onMounted,watch} from 'vue'
import {ElMessage,ElMessageBox} from 'element-plus'
import {native,api,onState} from './bridge'
import {CircleCheck,Warning,InfoFilled,Switch,ArrowDown,Refresh,DocumentChecked,QuestionFilled,DataBoard,List,User,Setting} from '@element-plus/icons-vue'
const state=reactive({}),page=ref('work'),siteUser=ref(null),permissions=ref([]),busy=ref(false),error=ref(''),success=ref(''),rooms=ref([]),context=ref(null),anchorId=ref(null),preview=ref(null),pending=ref(null),bindRoom=ref(null)
const loginOpen=ref(false),captcha=ref({}),credentials=reactive({username:'',password:'',code:''}),roomId=ref(null),detail=reactive({}),assigned=ref([]),expected=ref([]),copyRoom=ref(null),range=ref('6'),dates=ref([]),logCategory=ref('全部')
const sessionDetail=ref(false),expandedDetails=ref(['details'])
const pageIcons={work:DataBoard,records:List,anchors:User,settings:Setting}
const manager=computed(()=>permissions.value.includes('*:*:*')||permissions.value.includes('live:metrics:manage'))
const pages=computed(()=>[['work','上报工作台'],['records','上报记录'],...(manager.value?[['anchors','主播分配']]:[]),['settings','设置与更新']])
const segmentMetrics=[{key:'gmvDelta',label:'成交金额',type:'money'},{key:'watchDelta',label:'观看人数',type:'number'},{key:'newFanDelta',label:'新增粉丝',type:'number'},{key:'dealDelta',label:'成交人数',type:'number'},{key:'adCostDelta',label:'投流消耗',type:'money'},{key:'exposureWatchRate',label:'进房率',type:'rate'},{key:'watchFollowRate',label:'转粉率',type:'rate'},{key:'watchInteractionRate',label:'互动率（估算）',type:'rate'},{key:'watchDealRate',label:'成交率',type:'rate'},{key:'presaleOrderDelta',label:'预售订单',type:'number'}]
const funnelMetrics=[['funnel_exposure_ucnt','直播间曝光人数','number'],['funnel_watch_ucnt','直播间观看人数','number'],['funnel_pay_ucnt','成交人数','number'],['funnel_interact_ucnt','内容互动人数','number'],['funnel_watch_interact_ratio','观看互动率（人数）','rate']]
const topMetrics=[['pay_amt','成交金额（不含异常交易）','money'],['follow_anchor_ucnt','新增粉丝数','number'],['stat_cost','千川消耗','money'],['pay_deposit_pre_order_cnt','预售订单数','number'],['presale_depay_deamt','预售定金金额','money']]
const primarySegmentMetrics=['gmvDelta','watchDelta','dealDelta','adCostDelta'].map(key=>segmentMetrics.find(m=>m.key===key))
const extraMetrics=[['watch_ucnt','累计观看人数','number'],['pay_ucnt','成交人数','number'],['watch_pay_ucnt_ratio','观看成交率','rate'],['live_show_watch_cnt_ratio','曝光观看率','rate'],['watch_interact_ucnt_ratio','观看互动率','rate'],['watch_follow_ucnt_ratio','观看关注率','rate']]
const money=v=>v==null?'—':Number(v).toLocaleString('zh-CN',{minimumFractionDigits:2,maximumFractionDigits:2}),dt=v=>v?String(v).replace('T',' ').slice(0,19):'—',date=v=>`${v.getFullYear()}-${String(v.getMonth()+1).padStart(2,'0')}-${String(v.getDate()).padStart(2,'0')}`
const rawMetric=field=>{const value=state.values?.[field[0]];return value==null?'—':field[2]==='money'?'¥'+money(value/100):field[2]==='rate'?(value*100).toFixed(2)+'%':Number(value).toLocaleString('zh-CN')}
const segmentValue=(row,field)=>row[field.key]==null?'—':field.type==='money'?'¥'+money(row[field.key]):field.type==='rate'?Number(row[field.key]).toFixed(2)+'%':Number(row[field.key]).toLocaleString('zh-CN')
const source=v=>({APP:'App上报',PLUGIN:'插件上报',MANUAL:'人工补录',AUTO:'系统计算',ADJUSTED:'补录重算'}[v]||v)
const selectedAnchor=computed(()=>context.value?.anchors?.find(u=>String(u.userId)===String(anchorId.value))?.userName||'')
const recordRows=computed(()=>(detail.sessions||[]).flatMap(s=>(s.segments||[]).map(g=>({...g,liveStartTime:s.liveStartTime,sessionId:s.sessionId}))))
const duration=r=>{const n=Math.round((new Date(dt(r.endTime).replace(' ','T'))-new Date(dt(r.startTime).replace(' ','T')))/60000);return `${Math.floor(n/60)}小时${n%60}分`}
const filteredLogs=computed(()=>(state.logs||[]).filter(s=>logCategory.value==='全部'||({采集:/指标|采集|响应|请求|页面/,上传:/上传|上报|预览/,登录:/登录|账号/,更新:/更新|安装|版本/}[logCategory.value]).test(s)).join('\n'))
const baselineStart=computed(()=>context.value?.effectiveBaseline?.capturedAt||context.value?.previousSnapshot?.capturedAt||state.liveStartTime)
const recentSegments=computed(()=>(context.value?.segments||[]).slice(-3).reverse())
const clock=v=>v?dt(v).slice(11,19):'—'
const shortDate=v=>{if(!v)return '待采集';const d=dt(v).slice(0,10);return d===date(new Date())?'今天':d}
const rangeEnd=(start,end)=>dt(start).slice(0,10)===dt(end).slice(0,10)?clock(end):shortDate(end)+' '+clock(end)
const intervalLabel=row=>`${shortDate(row.startTime)} ${clock(row.startTime)}–${rangeEnd(row.startTime,row.endTime)}`
function preciseDuration(row){const seconds=Math.max(0,Math.round((new Date(dt(row.endTime).replace(' ','T'))-new Date(dt(row.startTime).replace(' ','T')))/1000));if(!Number.isFinite(seconds))return '—';return [seconds>=3600?Math.floor(seconds/3600)+'小时':'',seconds>=60?Math.floor(seconds%3600/60)+'分':'',seconds%60+'秒'].join('')}
async function openCurrentRecords(){roomId.value=context.value?.roomId||roomId.value;range.value='0';await changePage('records')}
async function toggleStartup(enabled){try{await native('startup',{enabled});state.startupEnabled=enabled;ElMessage.success(enabled?'已开启登录Windows后自启':'已关闭开机自启')}catch(e){error.value=e.message}}
async function perform(action){if(busy.value)return;busy.value=true;error.value='';try{return await action()}catch(e){if(e!=='cancel'&&e!=='close')error.value=e.message||String(e)}finally{busy.value=false}}
async function loadUser(){try{const info=await api('/getInfo');siteUser.value=info.user;permissions.value=info.permissions||[];rooms.value=(await api('/live/metrics/rooms')).data||[];roomId.value??=rooms.value[0]?.roomId;await loadContext()}catch(e){siteUser.value=null;permissions.value=[];error.value=e.message}}
async function loadCaptcha(){try{captcha.value=await native('captcha')}catch(e){error.value=e.message}}
async function login(){await perform(async()=>{await native('login',{...credentials,uuid:captcha.value.uuid});credentials.password='';credentials.code='';await loadUser();if(siteUser.value)loginOpen.value=false;else await loadCaptcha()});if(loginOpen.value)await loadCaptcha()}
async function logout(){await perform(async()=>{await native('logout');siteUser.value=null;permissions.value=[];rooms.value=[];context.value=null;preview.value=null;page.value='work'})}
watch(loginOpen,value=>{if(value)loadCaptcha()})
function invalidatePreview(){preview.value=null;native('dirty',{value:!!pending.value||editOpen.value}).catch(()=>{})}
async function loadContext(){if(!siteUser.value||!state.roomId||!state.roomName)return;context.value=(await api('/live/desktop/context?'+new URLSearchParams({platformSessionId:state.roomId,roomName:state.roomName}))).data;if(!context.value.anchors?.some(a=>String(a.userId)===String(anchorId.value)))anchorId.value=context.value.anchors?.some(a=>String(a.userId)===String(siteUser.value.userId))?context.value.anchors.find(a=>String(a.userId)===String(siteUser.value.userId)).userId:null}
async function refresh(){invalidatePreview();await perform(async()=>{await native('collect');await loadContext()})}
function requestFromState(){const v=state.values;if(['live_show_watch_cnt_ratio','watch_follow_ucnt_ratio','watch_interact_ucnt_ratio','watch_pay_ucnt_ratio'].some(k=>v[k]==null))throw Error('新版五项采集已完成，旧版区间上报需要的指标已调整，待新版上报功能接入后使用');return {action:'REPORT',roomName:state.roomName,platformSessionId:String(state.roomId),liveStartTime:state.liveStartTime,idempotencyKey:crypto.randomUUID(),anchorUserId:anchorId.value,previousSnapshotId:context.value?.previousSnapshot?.snapshotId??null,capturedAt:state.capturedAtEpoch,watchTotal:v.watch_ucnt,interactionTotal:state.interactionEstimate,newFanTotal:v.follow_anchor_ucnt,dealTotal:v.pay_ucnt,gmvTotal:v.pay_amt/100,adCostTotal:v.stat_cost/100,presaleOrderTotal:v.pay_deposit_pre_order_cnt,exposureWatchRate:v.live_show_watch_cnt_ratio*100,watchFollowRate:v.watch_follow_ucnt_ratio*100,watchInteractionRate:v.watch_interact_ucnt_ratio*100,watchDealRate:v.watch_pay_ucnt_ratio*100}}
async function collectPreview(){await perform(async()=>{success.value='';preview.value=null;await native('collect');Object.assign(state,await native('state'));await loadContext();if(!state.complete||!state.roomName)throw Error('当前指标或直播间信息尚未收齐，详情见日志');if(!anchorId.value)throw Error('请选择实际上播主播');preview.value=(await api('/live/desktop/preview','POST',requestFromState())).data;await native('dirty',{value:true})})}
async function submit(){await perform(async()=>{if(Date.now()>preview.value.expiresAt)throw Error('预览已过期，请重新采集');if(preview.value.firstReport)await ElMessageBox.confirm('本次从开播开始计算。请确认之前没有其他主播漏报。','确认归属',{type:'warning'});const draft={ticket:preview.value.ticket,userId:siteUser.value.userId,anchor:selectedAnchor.value};await native('savePending',draft);pending.value=draft;const result=(await api('/live/desktop/submit','POST',{ticket:draft.ticket})).data;await native('clearPending');pending.value=null;preview.value=null;await native('dirty',{value:false});success.value=(result.duplicate?'已确认原上报成功':'上报成功')+'，记录编号 '+(result.segments?.at(-1)?.segmentId||'已保存');await loadContext()})}
async function recoverPending(){await perform(async()=>{if(String(pending.value.userId)!==String(siteUser.value?.userId))throw Error('请登录创建此草稿的网站账号');const result=(await api('/live/desktop/submit','POST',{ticket:pending.value.ticket})).data;await native('clearPending');pending.value=null;preview.value=null;await native('dirty',{value:false});success.value=result.duplicate?'原上报已成功，未重复写入':'上报成功';await loadContext()})}
async function discardPending(){await ElMessageBox.confirm('放弃本地草稿不会删除服务器记录。请先在记录页核对。','放弃草稿',{type:'warning'});await native('clearPending');pending.value=null;await native('dirty',{value:editOpen.value||!!preview.value})}
async function changePage(name){page.value=name;if(!siteUser.value&&name!=='settings'&&name!=='work'){loginOpen.value=true;return}if(name==='records'||name==='anchors')await perform(loadDetail)}
async function loadDetail(){if(!roomId.value)return;let begin,end;if(range.value==='custom'){[begin,end]=dates.value||[]}else{const today=new Date();end=date(today);begin=date(new Date(today.getTime()-Number(range.value)*86400000))}Object.assign(detail,(await api(`/live/metrics/rooms/${roomId.value}?`+new URLSearchParams({beginDate:begin||'',endDate:end||''}))).data);assigned.value=(detail.anchors||[]).map(u=>u.userId);expected.value=[...assigned.value]}
const assignmentChange=computed(()=>{const label=id=>detail.staff?.find(u=>u.userId===id)?.userName||id;return {add:assigned.value.filter(x=>!expected.value.includes(x)).map(label),remove:expected.value.filter(x=>!assigned.value.includes(x)).map(label)}})
async function copyAnchors(){await perform(async()=>{const room=(await api(`/live/metrics/rooms/${copyRoom.value}`)).data;assigned.value=(room.anchors||[]).map(u=>u.userId)})}
async function saveAnchors(){await perform(async()=>{await ElMessageBox.confirm(`新增：${assignmentChange.value.add.join('、')||'无'}；移除：${assignmentChange.value.remove.join('、')||'无'}。历史记录保留。`,'确认主播分配');await api(`/live/desktop/rooms/${roomId.value}/anchors`,'PUT',{expected:expected.value,selected:assigned.value});await loadDetail();await loadContext();ElMessage.success('主播分配已保存')})}
async function bindCurrent(){await perform(async()=>{if(!bindRoom.value)throw Error('请选择系统直播间');await api(`/live/desktop/rooms/${bindRoom.value}/binding`,'POST',{roomName:state.roomName});await loadContext()})}
const editOpen=ref(false),editing=ref(false),edit=reactive({}),editSession=ref(null),auditOpen=ref(false),audit=reactive({})
watch(editOpen,value=>native('dirty',{value:value||!!preview.value||!!pending.value}).catch(()=>{}))
const positions=computed(()=>{const rows=editSession.value?.segments||[],list=[{value:'FIRST',label:'第一场漏报',start:editSession.value?.liveStartTime,target:rows[0]}];for(let i=1;i<rows.length;i++)list.push({value:'BEFORE:'+rows[i].segmentId,label:'在'+rows[i].anchorName+'之前补录',start:rows[i].startTime,target:rows[i]});if(rows.length)list.push({value:'LAST',label:'最后一场漏报',start:rows.at(-1).endTime});return list})
const affected=computed(()=>positions.value.find(p=>p.value===edit.position)?.target)
function openCreate(){editing.value=false;Object.assign(edit,{sessionId:detail.sessions?.[0]?.sessionId,position:null,anchorUserId:null,startTime:null,endTime:null,dataMode:'MANUAL',reason:'',...Object.fromEntries(segmentMetrics.map(m=>[m.key,0]))});selectEditSession();editOpen.value=true}
function selectEditSession(){editSession.value=detail.sessions.find(s=>s.sessionId===edit.sessionId);edit.position=null;edit.startTime=null;edit.endTime=null}
function selectPosition(){const p=positions.value.find(p=>p.value===edit.position);edit.startTime=dt(p.start);edit.endTime=null;for(const m of segmentMetrics)edit[m.key]=Number(p.target?.[m.key]||0)}
function openEdit(row){editing.value=true;editSession.value=detail.sessions.find(s=>s.sessionId===row.sessionId);Object.assign(edit,{...row,startTime:dt(row.startTime),endTime:dt(row.endTime),dataMode:'MANUAL',reason:''});editOpen.value=true}
async function saveEdit(){await perform(async()=>{if(!edit.anchorUserId||!edit.endTime||!edit.startTime)throw Error('请完整填写主播和区间');if(editing.value&&!edit.reason?.trim())throw Error('请填写调整原因');if(!editing.value&&!edit.position)throw Error('请选择漏报位置');if(!editing.value&&affected.value&&segmentMetrics.every(m=>Number(edit[m.key])===Number(affected.value[m.key]||0)))throw Error('请将带入值改成漏报主播在该时段的实际数据');await ElMessageBox.confirm('保存后将重新计算受影响的相邻区间，请核对时间和数据。','确认保存');await api(editing.value?`/live/metrics/segments/${edit.segmentId}`:`/live/metrics/sessions/${edit.sessionId}/segments`,editing.value?'PUT':'POST',{...edit});editOpen.value=false;await loadDetail();await loadContext();ElMessage.success('已保存')})}
async function voidReport(){await perform(async()=>{if(!edit.reason?.trim())throw Error('请填写作废原因');await ElMessageBox.confirm('作废后将接续并重新计算下一条记录，历史操作保留。','确认作废',{type:'warning'});await api(`/live/metrics/segments/${edit.segmentId}/void`,'POST',{version:edit.version,reason:edit.reason});editOpen.value=false;await loadDetail();await loadContext()})}
async function showSnapshots(id){await perform(async()=>{Object.assign(audit,(await api(`/live/metrics/sessions/${id}`)).data);auditOpen.value=true})}
let lastCapture=''
onState(value=>{Object.assign(state,value);const key=String(value.capturedAtEpoch||'')+String(value.roomId||'')+String(value.roomName||'');if(key!==lastCapture){lastCapture=key;invalidatePreview();if(siteUser.value)loadContext().catch(e=>error.value=e.message)}})
onMounted(async()=>{await perform(async()=>{Object.assign(state,await native('state'));pending.value=await native('pending');await loadUser();if(!siteUser.value)loginOpen.value=true})})
</script>
